async function yalcaSignUp(e,a,n){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente. Veja o guia de configuração."};const{data:r,error:s}=await supabaseClient.auth.signUp({email:e.trim(),password:a});if(s)return{ok:!1,error:yalcaAuthErrorMessage(s)};if(!r.session)return{ok:!0,pendingEmailConfirmation:!0};const{error:i}=await supabaseClient.from("client_profiles").insert({email:e.trim(),store_name:n||""});return i?{ok:!1,error:"Conta criada, mas houve um erro ao registrar seu perfil: "+i.message}:{ok:!0,pendingEmailConfirmation:!1}}async function yalcaLogin(e,a){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente. Veja o guia de configuração."};const{data:n,error:r}=await supabaseClient.auth.signInWithPassword({email:e.trim(),password:a});return r?{ok:!1,error:yalcaAuthErrorMessage(r)}:{ok:!0,session:n.session}}async function yalcaIsLoggedIn(){if(!supabaseClient)return!1;const{data:e}=await supabaseClient.auth.getSession();return!!e.session}async function yalcaCurrentUser(){if(!supabaseClient)return null;const{data:e}=await supabaseClient.auth.getUser();return e.user||null}async function yalcaLogout(){supabaseClient&&await supabaseClient.auth.signOut()}async function yalcaRequireAuth(){return!!await yalcaIsLoggedIn()||(window.location.href="login.html",!1)}async function yalcaGetOwnProfile(){const e=await yalcaCurrentUser();if(!e)return null;const{data:a,error:n}=await supabaseClient.from("client_profiles").select("*").eq("user_id",e.id).maybeSingle();if(n)throw new Error(n.message);return a}async function yalcaIsAdmin(){const e=await yalcaCurrentUser();if(!e)return!1;const{data:a,error:n}=await supabaseClient.from("admins").select("user_id").eq("user_id",e.id).maybeSingle();return!n&&!!a}function yalcaAuthErrorMessage(e){const a=e&&e.message?e.message:"";return a.includes("Invalid login credentials")?"E-mail ou senha incorretos.":a.includes("Email not confirmed")?"Este e-mail ainda não foi confirmado. Verifique sua caixa de entrada.":a.includes("User already registered")?"Já existe uma conta com este e-mail. Tente entrar em vez de criar uma nova conta.":a.includes("Password should be at least")?"A senha precisa ter pelo menos 6 caracteres.":a||"Não foi possível concluir. Tente novamente em instantes."}